async function loadAdminPayments(){try{const d=await api('/api/admin/payments');const payments=d.payments||[];const sum=(status)=>payments.filter(p=>String(p.status).toLowerCase()===status.toLowerCase()).reduce((n,p)=>n+Number(p.amount||0),0);$('#paymentSummary').innerHTML=`<div class="admin-stat"><span>Paid and confirmed</span><b>${money(sum('Paid'))}</b></div><div class="admin-stat"><span>Awaiting verification</span><b>${money(sum('Pending'))}</b></div><div class="admin-stat"><span>Payment records</span><b>${payments.length}</b></div>`;const el=$('#adminPaymentsList');el.innerHTML=payments.length?d.payments.map(p=>`<article class="admin-order"><strong>Order #${p.order_id} · ${money(p.amount)}</strong><p>${escapeHtml(p.customer_name)} · ${escapeHtml(p.customer_phone)}<br>Method: ${escapeHtml(p.method)}<br>Status: <b>${escapeHtml(p.status)}</b> · Order: ${escapeHtml(p.order_status)}<br>Reference: ${escapeHtml(p.provider_reference||'Not provided')}<br><small>${escapeHtml(p.created_at)}</small></p>${p.status==='Pending'&&p.method!=='Cash on delivery'?`<form data-payment-reference="${p.id}"><label>Transaction reference<input name="reference" maxlength=120 required placeholder="Reference from official provider receipt"></label><button class="btn btn-outline">Save reference only</button><small>Saving a reference alone does not confirm payment.</small></form><form data-payment-verify="${p.id}" class="payment-verify-form"><label><input type="checkbox" name="confirmReceived" required> I checked my official merchant account and confirmed the money was received.</label><label>Verified transaction reference<input name="reference" maxlength=120 required placeholder="Exact provider transaction ID"></label><button class="btn btn-primary">Confirm payment received</button><small>Only use after checking the real transaction. This action marks the order paid.</small></form>`:''}</article>`).join(''):'<p>No payment records yet.</p>';$$('[data-payment-reference]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{const ref=new FormData(f).get('reference');const r=await api('/api/admin/payments/'+f.dataset.paymentReference+'/record-reference',{method:'POST',body:JSON.stringify({reference:ref})});toast(r.message);await loadAdminPayments();}catch(err){toast(err.message);}});$$('[data-payment-verify]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const d=new FormData(f);if(!d.get('confirmReceived'))return; if(!confirm('Have you personally checked the official merchant account and confirmed this exact payment was received?'))return;try{const r=await api('/api/admin/payments/'+f.dataset.paymentVerify+'/verify-manual',{method:'POST',body:JSON.stringify({reference:d.get('reference'),confirmReceived:true})});toast(r.message);await loadAdminPayments();await refreshAdmin();}catch(err){toast(err.message);}});}catch(e){$('#adminPaymentsList').textContent=e.message;}}
async function loadAdminSettings(){try{const d=await api('/api/admin/settings');const f=$('#settingsForm');for(const [k,v] of Object.entries(d.settings)){const el=f.elements[k];if(!el)continue;if(el.type==='checkbox')el.checked=String(v)==='true';else el.value=v;} }catch(e){$('#settingsMessage').textContent=e.message;}}
$('#settingsForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;const body={};for(const el of f.elements){if(!el.name)continue;body[el.name]=el.type==='checkbox'?String(el.checked):el.value;}try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(body)});$('#settingsMessage').textContent='All business, delivery, customer, notification and branding settings saved to the database.';await loadPublicSettings();updateCheckoutPaymentInstructions();toast('Settings saved.');}catch(err){$('#settingsMessage').textContent=err.message;}});
