async function loadAdminControlCentre(){
 try{
  const d=await api('/api/admin/control-centre'),s=d.summary||{};
  const cards=[['Customers',s.customers],['All orders',s.orders],['Active orders',s.active_orders],['Recorded paid money',money(s.paid_amount)],['Expenses',money(s.expenses)],['Estimated balance',money(s.estimated_balance)],['Pending payments',s.pending_payments],['Staff accounts',s.staff_accounts],['Active riders',s.active_riders],['Riders online',s.online_riders],['Active menu items',s.menu_items],['Inventory items',s.inventory_items],['Low-stock alerts',s.low_stock],['Open complaints',s.open_complaints],['Unread admin alerts',s.unread_notifications],['Staff checked in today',s.staff_checked_in_today]];
  $('#controlCentreStats').innerHTML=cards.map(([label,value])=>`<div class="admin-stat"><span>${escapeHtml(label)}</span><b>${value===undefined?'—':value}</b></div>`).join('');
  $('#controlCentreOrderStatuses').innerHTML=(d.orders_by_status||[]).length?d.orders_by_status.map(x=>`<article class="admin-order"><strong>${escapeHtml(x.status)}</strong><p>${Number(x.count)||0} orders</p></article>`).join(''):'<p>No orders recorded yet.</p>';
  $('#controlCentreActivity').innerHTML=(d.recent_activity||[]).length?d.recent_activity.map(x=>`<article class="admin-order"><strong>${escapeHtml(String(x.action||'').replace(/_/g,' '))}</strong><p>${escapeHtml(x.details||'')}<br><small>${escapeHtml(x.actor||'')} · ${escapeHtml(x.created_at||'')}</small></p></article>`).join(''):'<p>No activity recorded yet.</p>';
  $('#controlCentreSecurity').innerHTML=(d.security_events||[]).length?d.security_events.map(x=>`<article class="admin-order"><strong>${escapeHtml(String(x.event||'').replace(/_/g,' '))}</strong><p>${escapeHtml(x.username||'Unknown user')} · ${escapeHtml(x.details||'')}<br><small>${escapeHtml(x.created_at||'')} · IP ${escapeHtml(x.ip||'not recorded')}</small></p></article>`).join(''):'<p>No sign-in events recorded yet.</p>';
 }catch(e){$('#controlCentreStats').textContent='Could not load control centre: '+e.message;}
}
$('#refreshControlCentre')?.addEventListener('click',loadAdminControlCentre);
