async function loadAdminInventory(){try{const d=await api('/api/admin/inventory');const el=$('#adminInventoryList');el.innerHTML=d.items.length?d.items.map(x=>`<article class="admin-order"><strong>${escapeHtml(x.name)}</strong><p>Stock: ${Number(x.quantity)} ${escapeHtml(x.unit)} · Alert below ${Number(x.low_stock)} · Unit cost ${money(x.unit_cost)}<br><b>${Number(x.quantity)<=Number(x.low_stock)?'⚠️ LOW STOCK':'In stock'}</b></p><div class="admin-row-actions"><button type="button" data-stock-edit="${x.id}" data-qty="${x.quantity}" data-low="${x.low_stock}" data-cost="${x.unit_cost}">Update stock</button><button type="button" data-stock-delete="${x.id}">Remove</button></div></article>`).join(''):'<p>No inventory items yet.</p>';$$('[data-stock-edit]').forEach(b=>b.onclick=async()=>{const quantity=prompt('New quantity:',b.dataset.qty);if(quantity===null)return;const low_stock=prompt('Low-stock alert threshold:',b.dataset.low);if(low_stock===null)return;const unit_cost=prompt('Cost per unit in UGX:',b.dataset.cost);if(unit_cost===null)return;try{await api('/api/admin/inventory/'+b.dataset.stockEdit,{method:'PATCH',body:JSON.stringify({quantity:Number(quantity),low_stock:Number(low_stock),unit_cost:Number(unit_cost)})});loadAdminInventory();}catch(e){toast(e.message);}});$$('[data-stock-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this inventory item?'))return;try{await api('/api/admin/inventory/'+b.dataset.stockDelete,{method:'DELETE'});loadAdminInventory();}catch(e){toast(e.message);}});}catch(e){$('#adminInventoryList').textContent=e.message;}}
async function loadAdminFinance(){try{const [f,e]=await Promise.all([api('/api/admin/finance'),api('/api/admin/expenses')]);$('#financeSummary').innerHTML=`<div class="admin-stat"><span>Recorded paid sales</span><b>${money(f.revenue)}</b></div><div class="admin-stat"><span>Recorded expenses</span><b>${money(f.expenses)}</b></div><div class="admin-stat"><span>Estimated balance</span><b>${money(f.estimated_profit)}</b></div>`;$('#adminExpensesList').innerHTML=e.expenses.length?e.expenses.map(x=>`<article class="admin-order"><strong>${escapeHtml(x.title)} · ${money(x.amount)}</strong><p>${escapeHtml(x.category)} · ${escapeHtml(x.expense_date)}<br>${escapeHtml(x.notes||'')}</p><button type="button" data-expense-delete="${x.id}">Remove expense</button></article>`).join(''):'<p>No expenses recorded.</p>';$$('[data-expense-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this expense record?'))return;try{await api('/api/admin/expenses/'+b.dataset.expenseDelete,{method:'DELETE'});loadAdminFinance();}catch(err){toast(err.message);}});}catch(e){$('#financeSummary').textContent=e.message;}}
