async function loadAdvancedControls(){
 try{
  const [tax,refunds,staff,staffAccounts,attendance,recipes,inventory,menu,complaints]=await Promise.all([api('/api/admin/tax-settings'),api('/api/admin/refunds'),api('/api/admin/staff'),api('/api/admin/staff-accounts'),api('/api/admin/attendance'),api('/api/admin/recipes'),api('/api/admin/inventory'),api('/api/menu'),api('/api/admin/complaints')]);
  $('#taxSettingsForm').elements.tax_percent.value=tax.tax_percent;
  const staffOpts=staff.staff.map(x=>`<option value="${x.id}">${escapeHtml(x.name)} — ${escapeHtml(x.role)}</option>`).join('');$('#staffAccountMember').innerHTML=staffOpts||'<option value="">Add staff records first</option>';$('#attendanceMember').innerHTML=staffOpts||'<option value="">Add staff records first</option>';
  const staffRoleOptions=['Manager','Cashier','Chef','Inventory','Customer support','Kitchen supervisor','Delivery coordinator','Marketing','Branch manager','Finance'];const staffPermissionOptions=[['orders','Orders'],['kitchen','Kitchen'],['menu','Food menu'],['customers','Customers'],['inventory','Inventory'],['payments','Payments'],['reports','Reports'],['promotions','Promotions'],['riders','Riders'],['support','Customer support'],['suppliers','Suppliers'],['branches','Branches']];
  $('#staffAccountList').innerHTML=staffAccounts.accounts.length?staffAccounts.accounts.map(x=>{const perms=JSON.parse(x.permissions_json||'[]');return `<article class="admin-order staff-access-card"><b>${escapeHtml(x.name||x.username)} · @${escapeHtml(x.username)}</b><p>${x.active?'Active':'Disabled'} account · Created ${escapeHtml(x.created_at||'')}</p><label>Role<select data-staff-role="${x.id}">${staffRoleOptions.map(r=>`<option ${x.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label>Allowed sections <select multiple size="5" data-staff-permissions="${x.id}">${staffPermissionOptions.map(([v,l])=>`<option value="${v}" ${perms.includes(v)?'selected':''}>${l}</option>`).join('')}</select></label><div class="admin-row-actions"><button type="button" data-staff-account-save="${x.id}">Save role & sections</button><button type="button" data-staff-account-toggle="${x.id}" data-active="${x.active?0:1}">${x.active?'Disable account':'Enable account'}</button></div></article>`}).join(''):'<p>No staff accounts created.</p>';
  $('#attendanceList').innerHTML=attendance.attendance.length?attendance.attendance.map(x=>`<article class="admin-order"><b>${escapeHtml(x.name)}</b><p>${escapeHtml(x.attendance_date)} · In: ${escapeHtml(x.check_in||'—')} · Out: ${escapeHtml(x.check_out||'—')}</p></article>`).join(''):'<p>No attendance records.</p>';
  $('#recipeMenu').innerHTML=menu.menu.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('');const invOpts=inventory.items.map(x=>`<option value="${x.id}">${escapeHtml(x.name)} (${escapeHtml(x.unit)})</option>`).join('');$('#recipeInventory').innerHTML=invOpts;$('#wastageItem').innerHTML=invOpts;
  $('#recipeList').innerHTML=recipes.recipes.length?recipes.recipes.map(x=>`<article class="admin-order"><b>${escapeHtml(x.menu_name)}</b><p>${Number(x.quantity)} ${escapeHtml(x.unit)} of ${escapeHtml(x.inventory_name)} per meal</p><button type="button" data-recipe-delete="${x.id}">Remove mapping</button></article>`).join(''):'<p>No recipe mappings yet.</p>';
  $('#refundList').innerHTML=refunds.refunds.length?refunds.refunds.map(x=>`<article class="admin-order"><b>Refund #${x.id} · Order #${x.order_id} · ${money(x.amount)}</b><p>${escapeHtml(x.customer_name||'Customer')} · ${escapeHtml(x.reason)}<br>Status: ${escapeHtml(x.status)} · Provider ref: ${escapeHtml(x.provider_reference||'—')}</p><div class="admin-row-actions">${x.status==='Approved'&&x.payment_status==='Paid'&&x.provider_transaction_id?`<button type="button" class="btn btn-primary" data-refund-process="${x.id}">Submit Flutterwave refund</button>`:''}<select data-refund-status="${x.id}"><option ${x.status==='Requested'?'selected':''}>Requested</option><option ${x.status==='Approved'?'selected':''}>Approved</option><option ${x.status==='Processing'?'selected':''}>Processing</option><option ${x.status==='Completed'?'selected':''}>Completed</option><option ${x.status==='Rejected'?'selected':''}>Rejected</option><option ${x.status==='Cancelled'?'selected':''}>Cancelled</option></select><input data-refund-ref="${x.id}" placeholder="Provider refund reference" value="${escapeHtml(x.provider_reference||'')}"><button type="button" data-refund-save="${x.id}">Update</button></div></article>`).join(''):'<p>No refunds recorded.</p>';
  $('#complaintList').innerHTML=complaints.complaints.length?complaints.complaints.map(x=>`<article class="admin-order"><b>${escapeHtml(x.subject)} · ${escapeHtml(x.customer_name||'Customer')}</b><p>${escapeHtml(x.message)}<br>Order: ${x.order_id||'—'} · Status: ${escapeHtml(x.status)}</p><input data-complaint-note="${x.id}" placeholder="Admin response / internal note" value="${escapeHtml(x.admin_note||'')}"><select data-complaint-status="${x.id}"><option ${x.status==='Open'?'selected':''}>Open</option><option ${x.status==='In progress'?'selected':''}>In progress</option><option ${x.status==='Resolved'?'selected':''}>Resolved</option><option ${x.status==='Closed'?'selected':''}>Closed</option></select><button type="button" data-complaint-save="${x.id}">Save complaint update</button></article>`).join(''):'<p>No complaints recorded.</p>';
  $$('[data-staff-account-toggle]').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/staff-accounts/'+b.dataset.staffAccountToggle,{method:'PATCH',body:JSON.stringify({active:Number(b.dataset.active)})});loadAdvancedControls();}catch(e){toast(e.message);}});
  $$('[data-staff-account-save]').forEach(b=>b.onclick=async()=>{const id=b.dataset.staffAccountSave;const role=$(`[data-staff-role="${id}"]`).value;const permissions=Array.from($(`[data-staff-permissions="${id}"]`).selectedOptions).map(o=>o.value);try{await api('/api/admin/staff-accounts/'+id,{method:'PATCH',body:JSON.stringify({role,permissions})});toast('Staff role and assigned sections saved.');loadAdvancedControls();}catch(e){toast(e.message);}});
  $$('[data-recipe-delete]').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/recipes/'+b.dataset.recipeDelete,{method:'DELETE'});loadAdvancedControls();}catch(e){toast(e.message);}});
  $$('[data-refund-process]').forEach(b=>b.onclick=async()=>{if(!confirm('Submit this approved refund to Flutterwave now? Check the provider dashboard before retrying if the request times out.'))return;b.disabled=true;try{const result=await api('/api/admin/refunds/'+b.dataset.refundProcess+'/process-flutterwave',{method:'POST',body:JSON.stringify({})});toast(result.message);await loadAdvancedControls();}catch(e){toast(e.message);}finally{b.disabled=false;}});
  $$('[data-refund-save]').forEach(b=>b.onclick=async()=>{const id=b.dataset.refundSave;try{await api('/api/admin/refunds/'+id,{method:'PATCH',body:JSON.stringify({status:$(`[data-refund-status="${id}"]`).value,provider_reference:$(`[data-refund-ref="${id}"]`).value})});loadAdvancedControls();}catch(e){toast(e.message);}});
  $$('[data-complaint-save]').forEach(b=>b.onclick=async()=>{const id=b.dataset.complaintSave;try{await api('/api/admin/complaints/'+id,{method:'PATCH',body:JSON.stringify({status:$(`[data-complaint-status="${id}"]`).value,admin_note:$(`[data-complaint-note="${id}"]`).value})});loadAdvancedControls();}catch(e){toast(e.message);}});
 }catch(e){toast('Advanced controls: '+e.message);}
}
