$('#restoreBackupForm')?.addEventListener('submit',async e=>{e.preventDefault();const file=e.currentTarget.elements.backup.files[0];if(!file)return; if(!confirm('Restoring replaces the current live database. Have you downloaded a fresh backup first?'))return;try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});const result=await api('/api/admin/backup/restore',{method:'POST',body:JSON.stringify({database_base64:data})});$('#restoreMessage').textContent=result.message;}catch(err){$('#restoreMessage').textContent=err.message;}});

function distanceKm(aLat,aLng,bLat,bLng){const rad=x=>x*Math.PI/180,R=6371,dLat=rad(bLat-aLat),dLng=rad(bLng-aLng),v=Math.sin(dLat/2)**2+Math.cos(rad(aLat))*Math.cos(rad(bLat))*Math.sin(dLng/2)**2;return 2*R*Math.asin(Math.sqrt(v));}
async function loadLiveLocations(){try{const d=await api('/api/admin/live-locations');const el=$('#liveLocationsList');const orders=d.orders||[];$('#liveLocationsUpdated').textContent='Last refreshed: '+new Date(d.updated_at||Date.now()).toLocaleTimeString();el.innerHTML=orders.length?orders.map(o=>{const hasC=o.customer_lat!==null&&o.customer_lng!==null&&Number.isFinite(Number(o.customer_lat))&&Number.isFinite(Number(o.customer_lng));const hasR=o.rider_lat!==null&&o.rider_lng!==null&&Number.isFinite(Number(o.rider_lat))&&Number.isFinite(Number(o.rider_lng));const dist=hasC&&hasR?distanceKm(Number(o.rider_lat),Number(o.rider_lng),Number(o.customer_lat),Number(o.customer_lng)):null;const hasRestaurant=d.restaurant&&d.restaurant.lat!==null&&d.restaurant.lng!==null&&Number.isFinite(Number(d.restaurant.lat))&&Number.isFinite(Number(d.restaurant.lng));const restaurantToCustomer=hasC&&hasRestaurant?distanceKm(Number(d.restaurant.lat),Number(d.restaurant.lng),Number(o.customer_lat),Number(o.customer_lng)):null;const riderToRestaurant=hasR&&hasRestaurant?distanceKm(Number(o.rider_lat),Number(o.rider_lng),Number(d.restaurant.lat),Number(d.restaurant.lng)):null;const customerLink=hasC?`<a target="_blank" rel="noopener" href="https://www.google.com/maps?q=${Number(o.customer_lat)},${Number(o.customer_lng)}">Open customer pin ↗</a>`:'GPS pin not shared; use written address';const riderLink=hasR?`<a target="_blank" rel="noopener" href="https://www.google.com/maps?q=${Number(o.rider_lat)},${Number(o.rider_lng)}">Open rider position ↗</a>`:'Rider GPS not received';const route=hasR?(hasC?`https://www.google.com/maps/dir/?api=1&origin=${Number(o.rider_lat)},${Number(o.rider_lng)}&destination=${Number(o.customer_lat)},${Number(o.customer_lng)}`:`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(o.delivery_address||'')}`):'';return `<article class="admin-order"><strong>Order #${Number(o.id)} · ${escapeHtml(o.status)}</strong><p><b>Customer:</b> ${escapeHtml(o.customer_name)} · ${escapeHtml(o.customer_phone||'')}<br><b>Address:</b> ${escapeHtml(o.delivery_address||'')}<br><b>Rider:</b> ${escapeHtml(o.rider_name||'Not assigned')}</p><p>📍 Customer: ${customerLink}<br>🚴 Rider: ${riderLink}</p><p>${dist===null?'Rider-to-customer distance unavailable until both GPS pins are shared.':`Approximate straight-line rider-to-customer distance: <b>${dist.toFixed(2)} km</b> (not road distance).`}<br>${restaurantToCustomer===null?'Set restaurant GPS in Settings to calculate restaurant-to-customer distance.':`Approximate restaurant-to-customer distance: <b>${restaurantToCustomer.toFixed(2)} km</b> (straight-line).`}<br>${riderToRestaurant===null?'Rider-to-restaurant distance unavailable.':`Approximate rider-to-restaurant distance: <b>${riderToRestaurant.toFixed(2)} km</b> (straight-line).`}</p>${o.rider_updated_at?`<small>Rider last GPS update: ${escapeHtml(o.rider_updated_at)}</small>`:''}${route?`<p><a class="btn btn-outline" target="_blank" rel="noopener" href="${route}">Open delivery route in Google Maps ↗</a></p>`:''}${hasR?`<iframe title="Rider map for order ${Number(o.id)}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" width="100%" height="210" style="border:0;border-radius:12px" src="https://maps.google.com/maps?q=${Number(o.rider_lat)},${Number(o.rider_lng)}&z=15&output=embed"></iframe>`:''}</article>`;}).join(''):'<p>No active deliveries. New orders will appear here once placed.</p>';}catch(e){$('#liveLocationsList').textContent=e.message;}}
$('#refreshLiveLocations')?.addEventListener('click',loadLiveLocations);
// Reliable admin navigation: every page is shown first, then its own data is refreshed.
// The common overview/menu/order/customer/rider/promotion data is refreshed together.
async function showAdminPage(pageId){
 const page=$('#'+pageId);
 if(!page||!page.classList.contains('admin-page')){toast('That admin section could not be found.');return;}
 $$('.admin-page').forEach(section=>{section.classList.toggle('active',section.id===pageId);section.setAttribute('aria-hidden',section.id===pageId?'false':'true');});
 $$('[data-admin-page]').forEach(btn=>{const active=btn.dataset.adminPage===pageId;btn.classList.toggle('active',active);if(active)btn.setAttribute('aria-current','page');else btn.removeAttribute('aria-current');});
 const main=$('.admin-main');if(main)main.scrollTop=0;
 const loaders={
  controlCentrePage:loadAdminControlCentre,overview:refreshAdmin,menuPage:refreshAdmin,ordersPage:refreshAdmin,customersPage:refreshAdmin,ridersPage:refreshAdmin,promotionsPage:refreshAdmin,
  paymentsPage:loadAdminPayments,settingsPage:loadAdminSettings,notificationsPage:loadAdminNotifications,reportsPage:loadAdminReports,
  inventoryPage:loadAdminInventory,expensesPage:loadAdminFinance,staffPage:loadAdminStaff,activityPage:loadAdminActivity,
  kitchenPage:loadKitchen,branchesPage:loadBranches,suppliersPage:loadSuppliers,loyaltyPage:loadLoyalty,
  advancedPage:loadAdvancedControls,locationsPage:loadLiveLocations,operationsPage:()=>window.loadBusinessTools?.()
 };
 const loader=loaders[pageId];
 if(loader){page.setAttribute('aria-busy','true');try{await loader();}catch(err){let box=page.querySelector('[data-section-error]');if(!box){box=document.createElement('p');box.dataset.sectionError='true';box.className='admin-section-error';page.prepend(box);}box.textContent='This section could not load: '+(err?.message||'Unknown error');}finally{page.removeAttribute('aria-busy');}}
}
$$('[data-admin-page]').forEach(btn=>btn.addEventListener('click',()=>{void showAdminPage(btn.dataset.adminPage);}));
const markAllAdminNotifications=$('#markAllAdminNotifications');if(markAllAdminNotifications)markAllAdminNotifications.addEventListener('click',async()=>{try{await api('/api/admin/notifications/read-all',{method:'PATCH'});await loadAdminNotifications();toast('Notifications marked read.');}catch(e){toast(e.message);}});const refreshAdminReports=$('#refreshAdminReports');if(refreshAdminReports)refreshAdminReports.addEventListener('click',loadAdminReports);
const adminLogoutSettings=$('#adminLogoutSettings');if(adminLogoutSettings)adminLogoutSettings.addEventListener('click',()=>$('#adminLogout').click());
let adminPollTimer=null;
function startAdminPolling(){if(adminPollTimer)clearInterval(adminPollTimer);adminPollTimer=setInterval(async()=>{if(!$('#adminModal').classList.contains('open')||$('#adminDashboard').classList.contains('hidden'))return;try{const d=await api('/api/admin/orders');const newest=d.orders.reduce((max,o)=>Math.max(max,Number(o.id)||0),0);if(lastAdminOrderId&&newest>lastAdminOrderId){toast('New food order received!');if('Notification'in window&&Notification.permission==='granted')new Notification('Eddys Kitchen',{body:'A new customer order has arrived.'});}lastAdminOrderId=Math.max(lastAdminOrderId,newest);await refreshAdmin();if($('#locationsPage')?.classList.contains('active'))await loadLiveLocations();}catch(_){ }},15000);}

(async()=>{try{const d=await api('/api/menu');state.menu=d.menu;renderCategories();renderMenu();renderCart();await loadPromotions();await loadPublicSettings();try{const m=await api('/api/me');state.customer=m.customer;updateAccountButton()}catch(_){}}catch(e){$('#menuGrid').innerHTML='<div class="empty-state">The menu could not load. Please restart the website server and refresh this page.</div>';}})();

const notifyButton=$('#notifyBtn');
if(notifyButton) notifyButton.addEventListener('click',async()=>{if(!('Notification' in window)){toast('Notifications are not supported by this browser.');return;}const permission=await Notification.requestPermission();toast(permission==='granted'?'Order notifications enabled.':'Notifications were not enabled.');});
let previousOrderStatuses={};
async function pollOrderUpdates(){if(!state.customer)return;try{const d=await api('/api/orders');for(const o of d.orders){const old=previousOrderStatuses[o.id];if(old&&old!==o.status&&'Notification'in window&&Notification.permission==='granted')new Notification('Eddys Kitchen order update',{body:`Order #${o.id}: ${o.status}`});previousOrderStatuses[o.id]=o.status;}}catch(_){}}
setInterval(pollOrderUpdates,20000);



